package org.humanjourney.core.progress;
import java.util.*;
import java.nio.file.*;
import java.io.*;
import java.util.concurrent.*;
import com.google.gson.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import org.mockito.MockedStatic;
import net.minecraft.SharedConstants;
import net.minecraft.server.Bootstrap;
import net.minecraft.core.*;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.server.packs.resources.*;
class ProgressSyncTest {
 static MockedStatic<net.minecraftforge.fml.ModLoader> loader;static final UUID SESSION=UUID.fromString("00000000-0000-0000-0000-000000000160");
 @BeforeAll static void bootstrap(){loader=mockStatic(net.minecraftforge.fml.ModLoader.class);loader.when(net.minecraftforge.fml.ModLoader::get).thenReturn(mock(net.minecraftforge.fml.ModLoader.class));SharedConstants.tryDetectVersion();Bootstrap.bootStrap();}
 @AfterAll static void close(){loader.close();}
 @AfterEach void clear(){ProgressStore.reset();}
 static ProgressView initial()throws Exception{return ProgressGraphTest.view(ProgressGraphTest.parse(ProgressGraphTest.example()),Map.of());}
 static ProgressPackets.Frame wire(ProgressPackets.Frame f){var b=new RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),RegistryAccess.fromRegistryOfRegistries(BuiltInRegistries.REGISTRY));try{ProgressPackets.CODEC.encode(b,f);assertTrue(b.readableBytes()<=ProgressPackets.MAX_PACKET);return ProgressPackets.CODEC.decode(b);}finally{b.release();}}
 static ProgressView large()throws Exception{var o=ProgressGraphTest.example();for(var n:o.getAsJsonArray("nodes"))n.getAsJsonObject().addProperty("description","Large description "+"x".repeat(1800));return ProgressGraphTest.view(ProgressGraphTest.parse(o),Map.of());}
 @Test void nativeCodecAtomicMultiPartReconstructionInReverseOrder()throws Exception{var view=large();var frames=ProgressPackets.frames(SESSION,1,view);assertTrue(frames.size()>1);var mirror=new ProgressMirror();for(int i=frames.size()-1;i>=0;i--){assertTrue(mirror.accept(wire(frames.get(i))));if(i>0)assertTrue(mirror.view().nodes().isEmpty());}assertEquals(view,mirror.view());}
 @Test void incompleteSnapshotKeepsCompletePreviousView()throws Exception{var mirror=new ProgressMirror();var old=initial();ProgressPackets.frames(SESSION,1,old).forEach(mirror::accept);var frames=ProgressPackets.frames(SESSION,2,large());mirror.accept(frames.getFirst());assertEquals(old,mirror.view());}
 @Test void conflictingFragmentsRejectWithoutPartialPublication()throws Exception{var mirror=new ProgressMirror();var frames=ProgressPackets.frames(SESSION,1,large());var p=frames.getFirst();mirror.accept(p);var bad=p.data();bad[0]^=1;assertFalse(mirror.accept(new ProgressPackets.Frame(p.session(),p.sequence(),p.part(),p.parts(),p.length(),bad,false)));assertFalse(mirror.problem().isEmpty());assertFalse(mirror.view().participant());}
 @Test void roleRevocationClearsAllGraphContentAndStalePacketsCannotRestoreIt()throws Exception{var mirror=new ProgressMirror();var prior=ProgressPackets.frames(SESSION,1,initial());prior.forEach(mirror::accept);assertTrue(mirror.view().participant());ProgressPackets.frames(SESSION,2,ProgressView.empty(false)).forEach(mirror::accept);prior.forEach(mirror::accept);assertEquals(ProgressView.empty(false),mirror.view());}
 @Test void resettingSharedScoresUpdatesExistingMirrorWithoutNewLedger()throws Exception{var graph=ProgressGraphTest.parse(ProgressGraphTest.example());var done=ProgressGraphTest.view(graph,Map.of("#we_can_stay",1));var mirror=new ProgressMirror();ProgressPackets.frames(SESSION,1,done).forEach(mirror::accept);assertEquals(ProgressView.State.COMPLETED,ProgressGraphTest.node(mirror.view(),"we_can_stay").state());ProgressPackets.frames(SESSION,2,initial()).forEach(mirror::accept);assertEquals(ProgressView.State.LOCKED,ProgressGraphTest.node(mirror.view(),"we_can_stay").state());}
 @Test void reconnectNewSessionAndLogoutClearDoNotRetainAnotherWorld()throws Exception{var mirror=new ProgressMirror();var old=ProgressPackets.frames(SESSION,5,initial());old.forEach(mirror::accept);var next=UUID.randomUUID();ProgressPackets.frames(next,1,ProgressView.empty(true)).forEach(mirror::accept);old.forEach(mirror::accept);assertTrue(mirror.view().nodes().isEmpty());mirror.clear();assertFalse(mirror.view().participant());ProgressPackets.frames(SESSION,1,initial()).forEach(mirror::accept);assertTrue(mirror.view().participant());}
 @Test void duplicateIdenticalFramesAreIdempotent()throws Exception{var mirror=new ProgressMirror();var frames=ProgressPackets.frames(SESSION,1,large());mirror.accept(frames.getFirst());assertTrue(mirror.accept(frames.getFirst()));frames.forEach(mirror::accept);assertEquals(large(),mirror.view());}
 @Test void joinRoleChangeReconnectAndStablePollingDelivery()throws Exception{var a=new ProgressDelivery();var b=new ProgressDelivery();assertTrue(a.needs(1,true,1));a.sent(1,true,1);for(int tick=0;tick<500;tick++)assertFalse(a.needs(1,true,1));assertTrue(b.needs(2,true,1));assertTrue(a.needs(1,true,2));assertTrue(a.needs(9,true,1));assertTrue(a.needs(1,false,1));a.sent(1,false,1);assertFalse(a.needs(1,false,9));assertTrue(a.needs(1,true,9));}
 @Test void sharedCivilizationViewIsIdenticalForTwoStudentsAndTeachers()throws Exception{var graph=ProgressGraphTest.parse(ProgressGraphTest.example());var scores=Map.of("#first_flame",1);var student=ProgressGraphTest.view(graph,scores);var teacher=ProgressGraphTest.view(graph,scores);assertEquals(student,teacher);assertEquals(student,ProgressView.parse(student.json()));}
 @Test void malformedOrOversizedPacketIsBoundedlyRejected(){assertThrows(IllegalArgumentException.class,()->new ProgressPackets.Frame(SESSION,1,0,129,ProgressPackets.MAX_SNAPSHOT+1,new byte[1],false));var b=new RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),RegistryAccess.fromRegistryOfRegistries(BuiltInRegistries.REGISTRY));try{b.writeBytes(new byte[ProgressPackets.MAX_PACKET+1]);assertTrue(ProgressPackets.CODEC.decode(b).invalid());assertEquals(0,b.readableBytes());}finally{b.release();}}
 Resource resource(String text)throws Exception{var r=mock(Resource.class);when(r.sourcePackId()).thenReturn("synthetic-pack");when(r.openAsReader()).thenAnswer(a->new BufferedReader(new StringReader(text)));return r;}
 void reload(String text)throws Exception{var manager=mock(ResourceManager.class);var loaded=text==null?Optional.<Resource>empty():Optional.of(resource(text));when(manager.getResource(ResourceLocation.parse(ProgressReloadListener.PATH))).thenReturn(loaded);var barrier=new PreparableReloadListener.PreparationBarrier(){public <T> CompletableFuture<T> wait(T value){return CompletableFuture.completedFuture(value);}};new ProgressReloadListener().reload(barrier,manager,Runnable::run,Runnable::run).join();}
 @Test void actualReloadRetainsWholeLastValidGraphOnInvalidAndClearsWhenAbsent()throws Exception{String text=ProgressGraphTest.example().toString().replace("toughasnails:purified_water_bottle","minecraft:potion");reload(text);var prior=ProgressStore.state();assertEquals(18,prior.graph().nodes().size());reload("{bad json");assertSame(prior.graph(),ProgressStore.state().graph());assertEquals(prior.revision(),ProgressStore.state().revision());assertTrue(ProgressStore.state().error().contains("synthetic-pack"));reload(null);assertTrue(ProgressStore.state().graph().nodes().isEmpty());assertTrue(ProgressStore.state().error().isEmpty());}
 @Test void oversizedResourceRejectsBeforeUnboundedParsing()throws Exception{reload(" ".repeat(ProgressGraph.MAX_JSON+1));assertTrue(ProgressStore.state().error().contains("1MiB"));assertTrue(ProgressStore.state().graph().nodes().isEmpty());}
 @Test void absentProductionGraphHasHelpfulParticipantFallback(){assertTrue(ProgressStore.state().graph().nodes().isEmpty());var view=ProgressView.project(ProgressStore.state().graph(),(o,h)->OptionalInt.empty());assertTrue(view.participant());assertTrue(view.nodes().isEmpty());assertTrue(view.message().contains("no civilization graph"));}
 @Test void sanitisedPacketDoesNotContainServerSelectorsConditionsOrHiddenText()throws Exception{var o=ProgressGraphTest.example();var n=ProgressGraphTest.node(o,"new_continent");n.addProperty("description","NEVER_SEND_THIS");var conditions=new JsonArray();conditions.add(ProgressGraphTest.condition("#secret_visibility"));n.add("visible_when",conditions);var v=ProgressGraphTest.view(ProgressGraphTest.parse(o),Map.of());String transmitted=new String(ProgressPackets.frames(SESSION,1,v).stream().map(ProgressPackets.Frame::data).reduce(new byte[0],(a,b)->{var bytes=Arrays.copyOf(a,a.length+b.length);System.arraycopy(b,0,bytes,a.length,b.length);return bytes;}),java.nio.charset.StandardCharsets.UTF_8);assertFalse(transmitted.contains("NEVER_SEND_THIS"));assertFalse(transmitted.contains("#secret_visibility"));assertFalse(transmitted.contains("#we_can_stay"));assertFalse(transmitted.contains("hj_civ"));}
 @Test void commonClassesContainNoMinecraftClientTypesAndNoProgressMutationPaths()throws Exception{for(String name:List.of("ProgressBootstrap","ProgressServer","ProgressStore","ProgressGraph","ProgressView","ProgressPackets","ProgressMirror","ProgressNetwork")){try(var in=ProgressSyncTest.class.getResourceAsStream("/org/humanjourney/core/progress/"+name+".class")){assertNotNull(in);assertFalse(new String(in.readAllBytes(),java.nio.charset.StandardCharsets.ISO_8859_1).contains("net/minecraft/client/"),name);}}String server=Files.readString(ProgressGraphTest.project().resolve("src/main/java/org/humanjourney/core/progress/ProgressServer.java"));assertTrue(server.contains("getPlayerScoreInfo"));for(String forbidden:List.of("getOrCreatePlayerScore","setScore(","performPrefixedCommand","getAdvancements()","SavedData"))assertFalse(server.contains(forbidden));}
 @Test void vanillaEntryIsAdditiveAndUnboundKeyHasNoDefaultConflict()throws Exception{String client=Files.readString(ProgressGraphTest.project().resolve("src/main/java/org/humanjourney/core/progress/client/ProgressClient.java"));assertTrue(client.contains("ScreenEvent.Init.Post"));assertTrue(client.contains("instanceof AdvancementsScreen"));assertTrue(client.contains("GLFW.GLFW_KEY_UNKNOWN"));assertFalse(client.contains("xaero"));String screen=Files.readString(ProgressGraphTest.project().resolve("src/main/java/org/humanjourney/core/progress/client/ProgressScreen.java"));assertFalse(screen.contains("net.minecraftforge.network"));assertFalse(screen.contains("sendCommand"));assertTrue(screen.contains("minecraft.setScreen(parent)"));}
}
